import{_ as i,o as t,c as n,a4 as s}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0038 — Pièces jointes des formulaires publics : dépôt en attente, type réel vérifié, antivirus livré inactif","description":"Extrait de docs/adr/0038-pieces-jointes-des-formulaires-publics.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0038 — Pièces jointes des formulaires publics : dépôt en attente, type réel vérifié, antivirus livré inactif","description":"Extrait de docs/adr/0038-pieces-jointes-des-formulaires-publics.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0038-pieces-jointes-des-formulaires-publics.md","filePath":"developpeurs/adr/0038-pieces-jointes-des-formulaires-publics.md"}'),r={name:"developpeurs/adr/0038-pieces-jointes-des-formulaires-publics.md"};function a(o,e,l,u,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0038--pièces-jointes-des-formulaires-publics--dépôt-en-attente-type-réel-vérifié-antivirus-livré-inactif" tabindex="-1">ADR-0038 — Pièces jointes des formulaires publics : dépôt en attente, type réel vérifié, antivirus livré inactif <a class="header-anchor" href="#adr-0038--pièces-jointes-des-formulaires-publics--dépôt-en-attente-type-réel-vérifié-antivirus-livré-inactif" aria-label="Permalink to &quot;ADR-0038 — Pièces jointes des formulaires publics : dépôt en attente, type réel vérifié, antivirus livré inactif {#adr-0038--pièces-jointes-des-formulaires-publics--dépôt-en-attente-type-réel-vérifié-antivirus-livré-inactif}&quot;">​</a></h1><p><strong>Date :</strong> 19 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §7.1, §7.2, §8.3 ; revue documentaire du 18/09/2026 (seule action <strong>bloquante</strong> de <code>docs/adr/actions-ouvertes.md</code>) ; clôt l&#39;action « offres d&#39;emploi » de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant">ADR-0017</a>, s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0015-captcha-non-configure-refus-de-soumission">ADR-0015</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0030-conservation-des-donnees-anonymisation">ADR-0030</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Quatre formulaires publics livrés déclarent des champs fichier :</p><ul><li>le CV <strong>obligatoire</strong>, la lettre de motivation et un autre document des deux candidatures du pack emploi ;</li><li>la pièce jointe de la saisine par voie électronique ;</li><li>le document joint d&#39;une demande de projet (pack agence) ;</li><li>la capture d&#39;écran d&#39;un signalement (pack développeurs).</li></ul><p>Aucune route publique ne permettait pourtant de déposer un fichier. Le mécanisme du Core pour les fichiers liés à une personne (ADR-0017 : accès par identifiant, jamais par nom, aucune énumération) n&#39;était servi qu&#39;en lecture. La soumission acceptait n&#39;importe quel UUID bien formé sans vérifier qu&#39;il désignait quoi que ce soit : un CV obligatoire se contentait d&#39;un identifiant inventé, et un agent n&#39;avait aucun moyen de lire une pièce jointe.</p><p>Trois questions étaient à trancher : quand le fichier est déposé, comment on se protège d&#39;un dépôt anonyme, et ce qu&#39;on vérifie du contenu. Un fichier déposé par un inconnu finit en effet ouvert sur le poste d&#39;un agent, ce qui est un vecteur classique de logiciel malveillant.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le fichier est déposé avant l&#39;ouverture de la demande, sans captcha par fichier.</strong></p><ul><li><code>POST /api/v1/public/forms/{clé}/attachments</code> (multipart : <code>organization_id</code>, <code>field</code>, <code>file</code>) contrôle le fichier, puis le stocke par le mécanisme de l&#39;ADR-0017 sous un porteur <strong>d&#39;attente</strong>, <code>pending_upload</code>. Ce porteur est le fichier lui-même : rattacher le dépôt au formulaire aurait rendu énumérables, sous un même porteur, les fichiers de personnes différentes.</li><li>L&#39;identifiant rendu est un secret, comme l&#39;identifiant d&#39;une soumission.</li><li>Un dépôt en attente n&#39;est <strong>lisible par personne</strong>, et il est <strong>effacé au bout d&#39;une heure</strong> s&#39;il n&#39;est rattaché à aucune demande (<code>PUBLIC_UPLOAD_PENDING_TTL_MINUTES=60</code> ; tâche <code>pending_upload_purge</code> de l&#39;ordonnanceur, toutes les 15 minutes).</li><li>Le verrou reste le captcha de l&#39;ouverture de la demande (ADR-0015). La route de dépôt a ses propres verrous : une limite de débit par adresse, distincte de celle des soumissions (<code>RATE_LIMIT_PUBLIC_UPLOAD_PER_IP=20/1h</code>, ADR-0031), et un plafond de taille (<code>PUBLIC_UPLOAD_MAX_MB=10</code>). Ce plafond est opposé à la longueur annoncée, puis au flux lui-même : la lecture est coupée au premier octet de trop.</li></ul><p><strong>2. Le rattachement est vérifié, pas supposé.</strong> À l&#39;ouverture et à chaque correction, chaque UUID d&#39;un champ fichier doit désigner un dépôt en attente de la même organisation, du même formulaire et du même champ, non échu. Lors d&#39;une correction, il peut aussi désigner un fichier déjà rattaché à cette demande.</p><ul><li>Sinon, le champ est en erreur, avec un <strong>message unique</strong> : distinguer l&#39;inconnu de l&#39;échu ou du fichier d&#39;un autre formulaire renseignerait sur l&#39;existence d&#39;un fichier qu&#39;on n&#39;a pas déposé.</li><li>Le fichier passe au porteur <code>form_submission</code>, celui que l&#39;export RGPD lisait déjà. Il suit l&#39;échéance de la saisie en attente, et vit avec le dossier une fois la demande confirmée.</li><li>Un fichier remplacé ou retiré par une correction est effacé tout de suite.</li></ul><p><strong>3. Le contenu est toujours contrôlé, et ce contrôle n&#39;est pas un réglage.</strong></p><ul><li>L&#39;extension du nom d&#39;origine doit être permise par le champ (<code>allowed_extensions</code> d&#39;un champ <code>file</code> ou <code>audio</code>). Un champ <code>media</code> n&#39;en déclare pas : il accepte des documents et des images (pdf, odt, doc, docx, jpg, jpeg, png), rien qui s&#39;exécute.</li><li>Le <strong>type réel</strong> est reconnu aux premiers octets : un <code>.exe</code> renommé en <code>.pdf</code> est refusé.</li><li>Le type rendu plus tard à l&#39;agent est déduit par le serveur, jamais pris au client, et servi avec <code>X-Content-Type-Options: nosniff</code>.</li><li>Une extension que le Core ne sait pas reconnaître est écartée, jamais acceptée sans contrôle.</li></ul><p><strong>4. Un antivirus est livré avec le Core, inactif</strong> (même principe que le captcha et le courriel, ADR-0027).</p><ul><li>Il s&#39;active en renseignant <code>ANTIVIRUS_CLAMD_URL</code> (par exemple <code>tcp://clamav:3310</code>). Le compose fournit le service <code>clamav</code> sous le profil <code>antivirus</code>.</li><li>Chaque fichier est alors analysé avant d&#39;être stocké. Un fichier infecté est refusé (422).</li><li>Un antivirus configuré mais injoignable ou trop lent (<code>ANTIVIRUS_TIMEOUT_SECONDS=30</code>) fait refuser le dépôt (503) : <strong>jamais d&#39;acceptation sans analyse</strong>, comme pour un captcha injoignable.</li><li>Une adresse illisible empêche le démarrage.</li></ul><p><strong>5. Un agent lit une pièce jointe depuis le dossier qu&#39;il a le droit de lire.</strong></p><ul><li><code>GET /api/v1/content-types/{clé}/entries/{id}/attachments/{fichier}</code> demande la permission de lecture du contenu, comme la lecture du dossier.</li><li>La route ne sert que ce que le dossier désigne : un fichier de la demande dont il est issu, et dont l&#39;identifiant figure dans ses données. Tout autre cas rend le même 404.</li><li>La lecture est <strong>toujours journalisée</strong> comme un accès à des données personnelles, avec l&#39;identifiant du fichier, jamais son nom.</li><li><code>GET /personal-files/{id}</code> reste réservé au porteur : il protège l&#39;archive d&#39;export RGPD.</li></ul><p><strong>6. Aucun orphelin.</strong> <code>personal_files</code> ne pend d&#39;aucune clé étrangère (ADR-0017). Chaque chemin qui fait disparaître une demande ou l&#39;anonymise efface donc ses fichiers lui-même :</p><ul><li>la purge des saisies abandonnées ;</li><li>l&#39;anonymisation, qui est le geste unique de l&#39;échéance de conservation et de l&#39;effacement accepté (ADR-0030, ADR-0032) ;</li><li>la suppression du dossier par un agent ;</li><li>la correction qui remplace un fichier.</li></ul><p><strong>Répéteurs : refus explicite.</strong> Aucun formulaire public livré ne place de champ fichier dans un bloc répété. La route de dépôt refuse un tel champ, et la soumission refuse toute valeur qui y figure : un UUID ne passe jamais sans contrôle.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Un captcha par fichier</strong></td><td>Trois épreuves de plus pour une candidature, et trois défis visibles avec un captcha tiers. La limite de débit, le plafond et l&#39;échéance d&#39;une heure bornent l&#39;abus sans rien coûter à l&#39;usager.</td></tr><tr><td><strong>Déposer les fichiers après l&#39;ouverture de la demande</strong></td><td>Il faudrait ouvrir une demande incomplète, donc relâcher le caractère obligatoire du CV à la validation, ce qui déplacerait le contrôle sans le simplifier.</td></tr><tr><td><strong>Faire confiance à l&#39;extension et au type annoncés par le navigateur</strong></td><td>Les deux sont choisis par le déposant. Un exécutable renommé passerait.</td></tr><tr><td><strong>Antivirus obligatoire</strong></td><td>Une installation neuve ne pourrait plus recevoir une seule candidature, alors que le contrôle du type réel écarte déjà l&#39;exécutable déguisé. Le brancher reste un geste d&#39;exploitation d&#39;une ligne.</td></tr><tr><td><strong>Ouvrir <code>GET /personal-files/{id}</code> aux agents qui ont une permission</strong></td><td>Cette route sert aussi l&#39;archive d&#39;export RGPD. L&#39;ouvrir à une permission en aurait fait le fichier le plus facile à obtenir du CMS (ADR-0017).</td></tr><tr><td><strong>Ajouter la dépendance <code>python-multipart</code></strong></td><td>Starlette recopie tout le corps sur disque avant que la route ne décide. Un analyseur borné de quelques dizaines de lignes (<code>app/core/multipart.py</code>) coupe au premier octet de trop, sans dépendance ni image à reconstruire.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Les quatre formulaires publics qui déclarent un fichier fonctionnent. Le pack emploi n&#39;est plus bloqué.</li><li>Un identifiant inventé ne passe plus pour une pièce jointe.</li><li>La règle de l&#39;ADR-0017 est tenue de bout en bout : les fichiers sont adressés par identifiant, aucune liste n&#39;existe, le nom d&#39;origine n&#39;apparaît dans aucune URL, et chaque lecture par un agent est journalisée.</li><li>Les pièces jointes figurent dans l&#39;export RGPD de la demande, et disparaissent avec elle.</li></ul><p><strong>Négatives</strong></p><ul><li>Sans antivirus branché, un document piégé qui <em>est</em> bien un document (macro, PDF malveillant) passe le contrôle du type. La notice demande à l&#39;exploitant d&#39;activer ClamAV dès qu&#39;il reçoit des candidatures.</li><li>Le démon ClamAV télécharge ses signatures au démarrage (plusieurs minutes, quelques centaines de mégaoctets). Tant qu&#39;il n&#39;écoute pas, les dépôts reçoivent un 503.</li><li>Un analyseur multipart maison est du code de plus à maintenir ; il est borné et couvert par les tests.</li><li>Un usager connecté ne retélécharge pas ses pièces jointes par <code>/personal-files</code> (leur porteur est la demande). Elles figurent en revanche dans son export.</li><li>Les copies d&#39;un dossier répliquées sur d&#39;autres sites ne donnent pas accès aux pièces jointes.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Route de dépôt, rattachement vérifié, lecture par un agent, effacement sur tous les chemins, adaptateur ClamAV inactif — <code>apps/api/app/forms/attachments.py</code>, <code>app/core/multipart.py</code>, <code>app/antivirus/</code>, recette <code>apps/api/tests/test_pieces_jointes.py</code>.</li><li>[x] Lien de téléchargement dans l&#39;écran d&#39;un dossier du back-office.</li><li>[ ] Éprouver ClamAV contre le démon réel (<code>docker compose --profile antivirus up</code>) : la recette n&#39;a exercé qu&#39;un faux démon qui parle le protocole clamd.</li><li>[x] Supprimer une organisation efface ses lignes <code>personal_files</code> en cascade, mais laisse les octets sur le disque. C&#39;était déjà vrai avant cette ADR, et les pièces jointes le rendent plus visible. <strong>Close le 28/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0058-cloture-d-une-organisation">ADR-0058</a></strong> : la clôture d&#39;une organisation efface les octets avant les lignes (<code>app/cli/organization_closure.py</code>, <code>tests/test_cloture_d_une_organisation.py</code>), et le balayage de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0060-balayage-des-fichiers-orphelins">ADR-0060</a> rattrape les orphelins.</li></ul>',30)])])}const f=i(r,[["render",a]]);export{m as __pageData,f as default};
